    @0x02bf  HhAddChild(HhBuildStaticTextAuto(IntConst(110), IntConst(156), StrConst("Bulánek Uzlík přibíjí svůj protest proti nevolnictví na dveře\nložnice. Tato událost doslova otřásla veřejností i všemi\ndosavadními teoriemi a zároveň dala podnět k pozdější vzpouře\nostatních Bulánků."), IntConst(2), 65711))
