    @0x08cf  HhAddChild(HhBuildStaticTextAuto(IntConst(110), IntConst(346), StrConst("První polštářová válka. Nepokoje v řadách Bulánků ústí v\nprvní ozbrojené konflikty mezi lidmi. Rozpoutává se 1. polštářová\nválka. Armáda Bulánků zahajuje agresivní defensivu na všech\nfrontách a zanechává za sebou jen spálená prostěradla. Nikdo\nnepamatuje větší masakr než k jakému došlo v bitvě u Lupan."), IntConst(2), 65711))
